    fn write_acceptance_stub_check_script(repo: &std::path::Path) {
        let script = r#"#!/usr/bin/env python3
import json
import sys
from pathlib import Path

cmd = sys.argv[1]

if cmd == "sync-tablet-support":
    print(json.dumps({
        "updated_paths": ["Tablet/INDEX.md", "Tablet/README.md"],
        "header_tex_path": "Tablet/header.tex",
        "index_md_path": "Tablet/INDEX.md",
        "readme_md_path": "Tablet/README.md",
    }))
elif cmd == "materialize-tablet-oleans":
    nodes = []
    i = 3
    while i < len(sys.argv):
        if sys.argv[i] == "--node" and i + 1 < len(sys.argv):
            nodes.append(sys.argv[i + 1])
            i += 2
        else:
            i += 1
    print(json.dumps({
        "requested_nodes": nodes,
        "materialized_nodes": nodes,
        "returncode": 0,
        "stdout": "",
        "stderr": "",
        "timed_out": False,
        "spawn_error": "",
    }))
elif cmd == "lean-compile-node":
    node = sys.argv[2]
    repo = Path(sys.argv[3])
    warnings = []
    source = repo / "Tablet" / f"{node}.lean"
    if source.exists():
        for raw_line in source.read_text(encoding="utf-8").splitlines():
            marker = "-- TEST-COMPILE-WARNING:"
            if marker not in raw_line:
                continue
            owner, shape, message = raw_line.split(marker, 1)[1].strip().split("|", 2)
            if shape == "replay":
                warnings.append(f"warning: Tablet/{owner}.lean:7:4: {message}")
            else:
                warnings.append(f"Tablet/{owner}.lean:7:4: warning: {message}")
    print(json.dumps({
        "returncode": 0,
        "stdout": "\n".join(warnings) + ("\n" if warnings else ""),
        "stderr": "",
        "timed_out": False,
        "spawn_error": "",
    }))
elif cmd == "print-axioms":
    node = sys.argv[2]
    print(json.dumps({
        "returncode": 0,
        "stdout": f"{node} does not depend on any axioms\n",
        "stderr": "",
        "timed_out": False,
        "spawn_error": "",
    }))
elif cmd == "lean-semantic-payloads":
    repo = Path(sys.argv[2])
    nodes = []
    i = 3
    while i < len(sys.argv):
        if sys.argv[i] == "--node" and i + 1 < len(sys.argv):
            nodes.append(sys.argv[i + 1])
            i += 2
        else:
            i += 1
    payloads = {}
    for node in nodes:
        lean_path = repo / "Tablet" / f"{node}.lean"
        payload = ""
        if lean_path.exists():
            for line in lean_path.read_text(encoding="utf-8").splitlines():
                stripped = line.strip()
                if stripped.startswith(("theorem ", "lemma ", "def ", "abbrev ", "instance ", "structure ", "inductive ", "class ", "axiom ")):
                    payload = stripped
                    break
        payloads[node] = {"ok": True, "payload": payload, "error": ""}
    print(json.dumps(payloads))
elif cmd == "local-closure-axioms":
    node = sys.argv[2]
    print(json.dumps({
        "request_id": 0,
        "node_name": node,
        "returncode": 0,
        "timed_out": False,
        "stdout": "",
        "stderr": "",
        "status": "ok",
        "kernel_axioms": [],
        "boundary_theorems": [],
        "strict_theorem_deps": [],
        "strict_definition_deps": [],
        "errors": [],
    }))
else:
    raise SystemExit(f"unexpected subcommand: {cmd}")
"#;
        let path = repo.join(".trellis/scripts/check.py");
        fs::create_dir_all(path.parent().unwrap()).expect("create checker dir");
        fs::write(&path, script).expect("write checker");
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            let mut perms = fs::metadata(&path).unwrap().permissions();
            perms.set_mode(0o755);
            fs::set_permissions(&path, perms).unwrap();
        }
    }

    fn cleanup_lint_capture_request(
        obligations: &[(&str, &str)],
    ) -> trellis_kernel::WrapperRequest {
        let task_obligations: BTreeMap<NodeId, CleanupTaskKind> = obligations
            .iter()
            .map(|(node, warning_text)| {
                (
                    NodeId::from(*node),
                    CleanupTaskKind::LintFix {
                        warning_text: (*warning_text).to_string(),
                    },
                )
            })
            .collect();
        let authorized_nodes = task_obligations.keys().cloned().collect();
        let mut request = WrapperRequest::default();
        request.worker_acceptance.validation_execution_plan = vec![
            WorkerValidationExecutionPlanStep::FinalCleanupPreserving {
                task_kind: Some(CleanupTaskKind::LintFix {
                    warning_text: String::new(),
                }),
                target_node: None,
                task_obligations,
                authorized_nodes,
                protected_statement_node_set: BTreeSet::new(),
            },
        ];
        request
    }

    fn seed_cleanup_lint_capture_repo(repo: &std::path::Path, sources: &[(&str, &str)]) {
        write_acceptance_stub_check_script(repo);
        fs::create_dir_all(repo.join("Tablet")).expect("create Tablet");
        fs::write(repo.join("lakefile.lean"), "package \"stub\"\n").expect("write lakefile");
        fs::write(repo.join("Tablet/Preamble.lean"), "").expect("write Preamble source");
        fs::write(repo.join("Tablet/Preamble.tex"), "").expect("write Preamble prose");
        for (node, source) in sources {
            fs::write(repo.join(format!("Tablet/{node}.lean")), source)
                .expect("write test node source");
            fs::write(
                repo.join(format!("Tablet/{node}.tex")),
                format!(
                    "\\begin{{theorem}}{node}\\end{{theorem}}\n\\begin{{proof}}Trivial.\\end{{proof}}\n"
                ),
            )
            .expect("write test node prose");
        }
    }

    #[test]
    fn cleanup_lint_capture_accepts_composite_persisted_prose_in_a_batch() {
        let tmp = tempdir().expect("tempdir");
        seed_cleanup_lint_capture_repo(
            tmp.path(),
            &[
                (
                    "Composite",
                    r#"import Tablet.Preamble
-- TEST-COMPILE-WARNING: Composite|direct|`List.mem_singleton` is an unused simp argument
-- TEST-COMPILE-WARNING: Composite|direct|`F` is an unused simp argument
-- TEST-COMPILE-WARNING: Composite|direct|try `simp at hkR` instead of `simpa using hkR`
-- TEST-COMPILE-WARNING: Composite|direct|`push_neg` has been deprecated. Prefer using `push Not` instead.
-- TEST-COMPILE-WARNING: Composite|direct|`Sym2.map_pair_eq` has been deprecated. Use `Sym2.map_mk` instead.
theorem Composite : True := by trivial
"#,
                ),
                (
                    "Sibling",
                    r#"import Tablet.Preamble
-- TEST-COMPILE-WARNING: Sibling|direct|unused variable 'x' [linter.unusedVariables]
theorem Sibling : True := by trivial
"#,
                ),
            ],
        );
        let request = cleanup_lint_capture_request(&[
            (
                "Composite",
                "`List.mem_singleton` and `F` are unused simp arguments; use `simp at hkR` instead of `simpa using hkR`; `push_neg` has been deprecated (prefer `push Not`); `Sym2.map_pair_eq` has been deprecated (use `Sym2.map_mk`).",
            ),
            ("Sibling", "unused variable 'x' [linter.unusedVariables]"),
        ]);

        let captured = capture_cleanup_lint_diagnostics(tmp.path(), &request, true, None)
            .expect("capture diagnostics through the production pre-burst supplier");

        assert_eq!(captured[&NodeId::from("Composite")].len(), 5);
        assert_eq!(captured[&NodeId::from("Sibling")].len(), 1);
        assert!(captured.values().all(|diagnostics| !diagnostics.is_empty()));
    }

    #[test]
    fn cleanup_lint_capture_rejects_target_stale_when_only_dependency_warns() {
        let tmp = tempdir().expect("tempdir");
        let warning = "`push_neg` has been deprecated. Prefer using `push Not` instead.";
        seed_cleanup_lint_capture_repo(
            tmp.path(),
            &[(
                "Stale",
                &format!(
                    "import Tablet.Preamble\n-- TEST-COMPILE-WARNING: Dependency|direct|{warning}\ntheorem Stale : True := by trivial\n"
                ),
            )],
        );
        let request = cleanup_lint_capture_request(&[("Stale", warning)]);

        let captured = capture_cleanup_lint_diagnostics(tmp.path(), &request, true, None)
            .expect("capture diagnostics through the production pre-burst supplier");

        assert_eq!(captured.get(&NodeId::from("Stale")), Some(&Vec::new()));
    }

    #[test]
    fn cleanup_lint_capture_judges_each_batch_member_independently() {
        let tmp = tempdir().expect("tempdir");
        let push_neg = "`push_neg` has been deprecated. Prefer using `push Not` instead.";
        seed_cleanup_lint_capture_repo(
            tmp.path(),
            &[
                (
                    "Composite",
                    r#"import Tablet.Preamble
-- TEST-COMPILE-WARNING: Composite|direct|`Sym2.map_pair_eq` has been deprecated. Use `Sym2.map_mk` instead.
theorem Composite : True := by trivial
"#,
                ),
                (
                    "Mismatch",
                    r#"import Tablet.Preamble
-- TEST-COMPILE-WARNING: Mismatch|direct|an unrelated warning
theorem Mismatch : True := by trivial
"#,
                ),
                (
                    "Replayed",
                    r#"import Tablet.Preamble
-- TEST-COMPILE-WARNING: Replayed|replay|`push_neg` has been deprecated. Prefer using `push Not` instead.
theorem Replayed : True := by trivial
"#,
                ),
            ],
        );
        let request = cleanup_lint_capture_request(&[
            (
                "Composite",
                "several findings, including deprecated `Sym2.map_pair_eq`; use `Sym2.map_mk`",
            ),
            ("Mismatch", "`missing_tactic` is deprecated"),
            ("Replayed", push_neg),
        ]);

        let captured = capture_cleanup_lint_diagnostics(tmp.path(), &request, true, None)
            .expect("capture diagnostics through the production pre-burst supplier");

        assert_eq!(captured[&NodeId::from("Composite")].len(), 1);
        assert!(captured[&NodeId::from("Mismatch")].is_empty());
        assert_eq!(captured[&NodeId::from("Replayed")], vec![push_neg]);
    }

    fn seed_assumptions_repo(repo: &std::path::Path, ordinary: bool) {
        write_acceptance_stub_check_script(repo);
        fs::create_dir_all(repo.join("Tablet")).expect("create Tablet");
        fs::write(repo.join("Tablet/Preamble.lean"), "").expect("write preamble lean");
        fs::write(repo.join("Tablet/Preamble.tex"), "").expect("write preamble tex");
        if ordinary {
            fs::write(
                repo.join("Tablet/Assumptions.lean"),
                "-- [TABLET NODE: Assumptions]\nimport Tablet.Preamble\n\n\
                 theorem Assumptions : True := by\n  trivial\n",
            )
            .expect("write ordinary assumptions lean");
            fs::write(
                repo.join("Tablet/Assumptions.tex"),
                "\\begin{theorem}Ordinary assumptions node.\\end{theorem}\n\
                 \\begin{proof}Trivial.\\end{proof}\n",
            )
            .expect("write ordinary assumptions tex");
        } else {
            fs::write(
                repo.join("Tablet/Assumptions.lean"),
                trellis_kernel::assumptions_registry::empty_assumptions_lean_scaffold(),
            )
            .expect("write assumptions lean");
            fs::write(
                repo.join("Tablet/Assumptions.tex"),
                trellis_kernel::assumptions_registry::empty_assumptions_tex_scaffold(),
            )
            .expect("write assumptions tex");
        }
    }

