    fn trust_v1_support_acceptance_context(
        repo: &std::path::Path,
        before_snapshot: BTreeMap<String, String>,
    ) -> serde_json::Value {
        let mut context =
            assumption_authoring_acceptance_context(repo, before_snapshot, false, false);
        context["request"]["trust_base_required_v1"] = serde_json::json!(true);
        context["request"]["trust_dormant_conditional_candidate_nodes"] = serde_json::json!([]);
        context["request"]["worker_contract"]["allowed_outcomes"] = serde_json::json!([
            "valid",
            "invalid",
            "stuck",
            "needs_restructure",
            "target_false_under_model"
        ]);
        context["request"]["is_pv"] = serde_json::json!(true);
        context["validation_kind"] = serde_json::json!("theorem_global");
        context["worker_acceptance"]["validation_kind"] = serde_json::json!("theorem_global");
        context["worker_acceptance"]["validation_execution_plan"] = serde_json::json!([]);
        context["active_node"] = serde_json::json!("");
        context["authorized_nodes"] = serde_json::json!([]);
        context["configured_targets"] = serde_json::json!([]);
        context["current_present_nodes"] = serde_json::json!(["Preamble"]);
        context["current_deps"] = serde_json::json!({"Preamble": []});
        context["current_target_claims"] = serde_json::json!({"Preamble": []});
        context["current_node_kinds"] = serde_json::json!({"Preamble": "preamble"});
        context
    }

    fn no_op_worker_payload(outcome: &str) -> serde_json::Value {
        let suggested = if outcome == "needs_restructure" {
            serde_json::json!(["Goal"])
        } else {
            serde_json::json!([])
        };
        serde_json::json!({
            "outcome": outcome,
            "summary": "no-op",
            "comments": "",
            "semantic_dep_updates": {},
            "target_claim_updates": {},
            "deleted_nodes": [],
            "difficulty_updates": {},
            "needs_restructure_suggested_nodes": suggested,
        })
    }

    #[test]
    fn cheap_newborn_claim_contract_rejects_before_semantic_plan_execution() {
        let tmp = tempdir().expect("tempdir");
        let repo = tmp.path();
        seed_assumptions_repo(repo, false);
        let before_snapshot = trellis_kernel::snapshot_tablet_dir(repo);
        let mut context =
            assumption_authoring_acceptance_context(repo, before_snapshot, false, false);
        context["validation_kind"] = serde_json::json!("theorem_global");
        context["worker_acceptance"]["validation_kind"] =
            serde_json::json!("theorem_global");
        context["worker_acceptance"]["validation_execution_plan"] = serde_json::json!([{
            "kind": "scoped_tablet",
            "allowed_nodes_mode": "all_present",
            "explicit_nodes": [],
        }]);

        fs::write(
            repo.join("Tablet/Helper.lean"),
            "import Tablet.Preamble\n\n-- [TABLET NODE: Helper]\ntheorem Helper : True := by\n-- BODY\n  trivial\n",
        )
        .expect("write newborn source");
        fs::write(
            repo.join("Tablet/Helper.tex"),
            "\\begin{lemma}Helper\\end{lemma}\n\\begin{proof}Trivial.\\end{proof}\n",
        )
        .expect("write newborn manuscript");

        let marker = repo.join("semantic-gate-ran");
        let script_path = repo.join(".trellis/scripts/check.py");
        fs::create_dir_all(script_path.parent().expect("script parent"))
            .expect("create script dir");
        let marker_literal =
            serde_json::to_string(marker.to_string_lossy().as_ref()).expect("quote marker path");
        fs::write(
            &script_path,
            format!(
                "from pathlib import Path\nPath({marker_literal}).write_text('ran')\nraise SystemExit(90)\n"
            ),
        )
        .expect("write semantic marker script");

        let output = check_trellis_worker_result_output(
            repo,
            context,
            no_op_worker_payload("valid"),
        )
        .expect("run worker acceptance preflight");
        assert!(!output.ok);
        assert!(output.contract_errors.iter().any(|error| {
            error.contains("explicitly report target_claim_updates for every new node")
                && error.contains("Helper")
        }));
        assert!(
            !marker.exists(),
            "the semantic validation plan must remain unexecuted after a cheap contract rejection"
        );
        assert!(output
            .validation_step_results
            .iter()
            .all(|step| step.build_output.is_empty()));
    }


