    /// Stage 7 (plan doc 32, N3; the S5 finding-5 strip pattern): stray
    /// `seam_repair` members — well-formed or malformed — are removed from
    /// NON-trust worker payloads BEFORE artifact validation, and left
    /// untouched on trust-required payloads.
    #[test]
    fn worker_checker_strips_seam_repair_on_non_trust_requests() {
        use crate::strip_seam_repair_from_untrusted_worker_payload;
        let payload = serde_json::json!({
            "outcome": "valid",
            "deviation_requests": {
                "dev-a": {
                    "path": "reference/dev-a.tex",
                    "summary": "s",
                    "affected_nodes": ["N"],
                    "seam_repair": {"malformed": ["any", "shape"]}
                },
                "dev-b": {
                    "path": "reference/dev-b.tex",
                    "summary": "s",
                    "affected_nodes": []
                }
            }
        });
        let mut stripped = payload.clone();
        strip_seam_repair_from_untrusted_worker_payload(&mut stripped, false);
        assert!(
            stripped["deviation_requests"]["dev-a"]
                .get("seam_repair")
                .is_none(),
            "the non-trust strip removes the stray regardless of shape: {stripped}"
        );
        assert_eq!(
            stripped["deviation_requests"]["dev-b"],
            payload["deviation_requests"]["dev-b"]
        );
        let mut kept = payload.clone();
        strip_seam_repair_from_untrusted_worker_payload(&mut kept, true);
        assert_eq!(kept, payload, "the trust-request path is unchanged");
    }

    /// Stage 5 fixes (S5 audit finding 1): the production `action:"init"`
    /// path (`seed_state_from_config` → `seed_trust_base_state`) refuses
    /// to install trust-base v1 into anything but a GENUINELY pristine
    /// state — and refuses BEFORE reading any seed file, so a preseeded
    /// polarity map, an in-flight request, station/marker state, or a
    /// non-Start stage each get the named refusal.  A pristine state
    /// proceeds past the check (and then fails on the missing seed file —
    /// the ordering proof).
    #[test]
    fn trust_init_refuses_non_pristine_state_with_named_error() {
        let directory = tempfile::tempdir().expect("tempdir");
        let metadata = RuntimeMetadata {
            trust_seed_manifest_path: Some(directory.path().join("SEED_MANIFEST.json")),
            ..RuntimeMetadata::default()
        };
        let assert_pristine_refusal = |state: &mut ProtocolState, shape: &str| {
            let error = crate::seed_trust_base_state(state, &metadata)
                .expect_err(&format!("{shape} must refuse trust installation"));
            assert!(
                error.contains("genuinely pristine"),
                "{shape}: named pristine refusal expected, got: {error}"
            );
            assert!(
                state.trust_base.mode != trellis_kernel::TrustBaseMode::RequiredV1,
                "{shape}: refusal must not install RequiredV1"
            );
        };
        // (a) The audit's exact vector: a cycle-zero state preseeded with
        // a live-Disprove polarity map.
        let mut state = ProtocolState::default();
        state.pv_live_polarity.insert(
            trellis_kernel::ChallengeTargetId::from("goal:correct"),
            trellis_kernel::ChallengePolarity::Disprove,
        );
        assert_pristine_refusal(&mut state, "preseeded Disprove map");
        // (b) An in-flight request.
        let mut state = ProtocolState::default();
        state.in_flight_request = Some(Box::new(state.expected_request(1, RequestKind::Review)));
        assert_pristine_refusal(&mut state, "in-flight request");
        // (c) Existing trust state.
        let mut state = ProtocolState::default();
        state.trust_base.last_fail_closed_reason = Some("prior trust state".into());
        assert_pristine_refusal(&mut state, "existing trust state");
        // (d) A non-Start stage.
        let mut state = ProtocolState::default();
        state.stage = Stage::Worker;
        assert_pristine_refusal(&mut state, "non-Start stage");
        // (e) A nonzero cycle.
        let mut state = ProtocolState::default();
        state.cycle = 3;
        assert_pristine_refusal(&mut state, "nonzero cycle");
        // Control: a pristine state passes the check and fails LATER on
        // the (deliberately missing) seed file — the check runs first.
        let mut state = ProtocolState::default();
        let error = crate::seed_trust_base_state(&mut state, &metadata)
            .expect_err("the fixture seed manifest does not exist");
        assert!(
            !error.contains("genuinely pristine"),
            "a pristine state must pass the pristine check: {error}"
        );
    }

    /// Stage 6: swap the fixture's routing-only entry for an EXECUTABLE
    /// seed contract + assessment-tool pin. `numeric_path` selects a generic
    /// signed-i64/full-width-u64 callable; otherwise the byte-RLE input schema.

    /// The production prose builder consumes only goal targets plus the
    /// callable manifest and emits a kernel-valid launch-half plan.  This
    /// fixture deliberately uses neutral names: eligibility is structural,
    /// not a registry of worked-example subjects.

    /// Stage 6 (revision 5, Codex R4-1 + Claude R4-F4): a
    /// A generic witness proposal carrying a negative `q : Std.I64` and a
    /// `w : Std.U64` above 2^53 (the decimal-string wire rule), injected
    /// through the real bridge surface:
    /// raw artifact JSON → artifact validator → checker rebuild → engine
    /// apply.  The first flip bounces record-absent, the VALIDATED
    /// proposal is stashed for the station, and the kernel-generated goal
    /// renders every operand parenthesized through the closed algebra.

    /// Stage 6 (revision 5): a generic proposal with an RLE
    /// byte-sequence witness generates a goal rendering
    /// `List.replicate … ++ …` exactly in the pinned tool's verified
    /// witness-helper shape — through the same real bridge surface.

    /// Stage 6 (R3-2 strip half): a witness proposal on a NON-trust run is
    /// stripped by the checker — the rebuilt response bytes OMIT the key
    /// entirely, never `"witness_proposal":null`.

    #[test]
    fn stuck_math_audit_checker_validates_memory_operations_against_repo() {
        use crate::check_trellis_stuck_math_audit_result_output;
        let tmp = tempdir().expect("tempdir");
        let repo = tmp.path().join("repo");
        std::fs::create_dir_all(&repo).unwrap();
        // Seed one active entry the audit may retire.
        trellis_kernel::process_memory::apply_file_ops(
            &repo,
            &[trellis_kernel::process_memory::ProcessMemoryFileOp::Add {
                entry_id: "pm-0001-route-x".into(),
                entry_type: "refuted-route".into(),
                coarse_node: "global".into(),
                title: "t".into(),
                body: "Route X refuted.".into(),
                cycle: 1,
                request_id: 1,
            }],
        )
        .unwrap();
        let mut request = trellis_kernel::WrapperRequest::default();
        request.id = 31;
        request.cycle = 9;
        request.kind = RequestKind::StuckMathAudit;
        request.coarse_dag_nodes = BTreeSet::from([NodeId::from("CoarseA")]);
        let request_json = serde_json::to_value(&request).unwrap();
        let payload = |ops: serde_json::Value| {
            serde_json::json!({
                "report": format!("## Claim being audited\n{}", "x".repeat(400)),
                "tasks": [],
                "probe_paths": [],
                "memory_operations": ops,
            })
        };

        // Valid: retire the existing active entry + add into a known cone.
        let ok = check_trellis_stuck_math_audit_result_output(
            request_json.clone(),
            payload(serde_json::json!([
                {"op": "retire", "entry_id": "pm-0001-route-x", "reason": "superseded by probe"},
                {"op": "add", "type": "constraint", "coarse_node": "CoarseA",
                 "title": "Interface bound", "body": "e_F = 2 b^(c/2) n."}
            ])),
            Some(&repo),
        )
        .expect("checker runs");
        assert!(ok.ok, "errors={:?}", ok.errors);
        let response = ok.response.expect("normalized response");
        assert_eq!(
            response["memory_operations"][0]["op"],
            serde_json::json!("retire"),
            "memory_operations must survive onto the normalized response"
        );

        // Unknown entry id → rejected against the repo worktree.
        let missing = check_trellis_stuck_math_audit_result_output(
            request_json.clone(),
            payload(serde_json::json!([
                {"op": "retire", "entry_id": "pm-9999-nope", "reason": "r"}
            ])),
            Some(&repo),
        )
        .expect("checker runs");
        assert!(!missing.ok);
        assert!(missing.errors[0].contains("does not name an existing"));

        // Regression (stuck-math-audit 2998, cycle 677): a short-form
        // `pm-<seq>` id (the LLM's natural abbreviation of the full
        // `pm-<seq>-<slug>` id) is rejected with an actionable error that
        // names the offending op and suggests the full id — never an
        // ok-status response whose real errors get lost downstream.
        let short_id = check_trellis_stuck_math_audit_result_output(
            request_json.clone(),
            payload(serde_json::json!([
                {"op": "supersede", "entry_id": "pm-0001", "type": "refuted-route",
                 "title": "t", "body": "b"}
            ])),
            Some(&repo),
        )
        .expect("checker runs");
        assert!(!short_id.ok);
        assert!(short_id.data.is_none() && short_id.response.is_none());
        assert!(
            short_id.errors[0].contains("memory_operations[0].entry_id `pm-0001`"),
            "error must name the offending op: {:?}",
            short_id.errors
        );
        assert!(
            short_id.errors[0].contains("did you mean `pm-0001-route-x`"),
            "error must suggest the full entry id: {:?}",
            short_id.errors
        );

        // Unknown coarse node → rejected against the request's coarse DAG.
        let bad_cone = check_trellis_stuck_math_audit_result_output(
            request_json.clone(),
            payload(serde_json::json!([
                {"op": "add", "type": "constraint", "coarse_node": "NotACone",
                 "title": "t", "body": "b"}
            ])),
            Some(&repo),
        )
        .expect("checker runs");
        assert!(!bad_cone.ok);
        assert!(bad_cone
            .errors
            .iter()
            .any(|e| e.contains("known coarse node")));

        // Operations without a repo path fail closed.
        let no_repo = check_trellis_stuck_math_audit_result_output(
            request_json,
            payload(serde_json::json!([
                {"op": "retire", "entry_id": "pm-0001-route-x", "reason": "r"}
            ])),
            None,
        )
        .expect("checker runs");
        assert!(!no_repo.ok);
        assert!(no_repo.errors[0].contains("require a repo_path"));
    }

