    /// W9: the witness-shape authoring lint reads `deferred_witness_fields`
    /// off the ACCEPTANCE CONTEXT, which is rebuilt from the bridge payload
    /// in a separate process. A field consumed downstream but absent from
    /// that JSON deserializes to its serde default and silently disables
    /// the lint in production while every unit test stays green — the bug
    /// class this file's `bridge_request_payload` comment enumerates. Pin
    /// the whole path: request -> bridge JSON -> round-trip -> gate output.

    #[test]
    fn bridge_payload_preserves_reachable_opaque_inventory() {
        let inventory = serde_json::json!({
            "schema": "trellis-reachable-opaque-inventory/v1",
            "entry_points": ["entry"],
            "unresolved_boundary_axioms": [{
                "name": "opaque.used",
                "stubs": "Nat -> Nat",
                "classification": "aeneas-stdlib-prim"
            }],
            "nodes": [{
                "node_id": "entry",
                "dependency_node_ids": [],
                "reviewed_boundary_calls": [],
                "unresolved_boundary_calls": ["opaque.used"]
            }]
        });
        let mut request = trellis_kernel::WrapperRequest::default();
        request.kind = RequestKind::Corr;
        request.reachable_opaque_inventory = inventory.clone();

        let payload = bridge_request_payload(&request, None, None).expect("bridge request payload");
        assert_eq!(payload["reachable_opaque_inventory"], inventory);
        let round_tripped: trellis_kernel::WrapperRequest =
            serde_json::from_value(payload).expect("round-trip request");
        assert_eq!(round_tripped.reachable_opaque_inventory, inventory);
    }

    #[test]
    fn bridge_worker_payload_preserves_coarse_dag_nodes_for_acceptance_context() {
        let tmp = tempdir().expect("tempdir");
        let mut request = trellis_kernel::WrapperRequest::default();
        request.id = 16;
        request.cycle = 6;
        request.kind = RequestKind::Worker;
        request.phase = Phase::ProofFormalization;
        request.mode = TaskMode::Restructure;
        request.active_node = Some(NodeId::from("ProofPhaseHelper"));
        request.current_present_nodes = BTreeSet::from([
            NodeId::from("CoarseA"),
            NodeId::from("CoarseB"),
            NodeId::from("ProofPhaseHelper"),
        ]);
        request.current_paper_approved_fingerprints.insert(
            TargetId::from("target_main"),
            "paper-approved-fp".to_string(),
        );
        request.coarse_dag_nodes =
            BTreeSet::from([NodeId::from("CoarseA"), NodeId::from("CoarseB")]);
        request.worker_acceptance.enabled = true;
        request.worker_acceptance.validation_kind = WorkerValidationKind::ProofRestructure;

        let payload = bridge_request_payload(&request, None, None).expect("bridge request payload");

        assert_eq!(
            payload["coarse_dag_nodes"],
            serde_json::json!(["CoarseA", "CoarseB"])
        );
        assert_eq!(
            payload["worker_contract"]["scope_contract"]["coarse_dag_nodes"],
            serde_json::json!(["CoarseA", "CoarseB"])
        );
        assert_eq!(
            payload["current_paper_approved_fingerprints"],
            serde_json::json!({"target_main": "paper-approved-fp"})
        );

        let round_tripped: trellis_kernel::WrapperRequest =
            serde_json::from_value(payload).expect("round-tripped wrapper request");
        let acceptance = prepare_worker_gate_output(tmp.path(), &round_tripped, false, None, None)
            .expect("prepared worker gate output");

        assert_eq!(
            acceptance.coarse_dag_nodes,
            BTreeSet::from([NodeId::from("CoarseA"), NodeId::from("CoarseB")])
        );
        assert_eq!(
            acceptance.request["worker_contract"]["scope_contract"]["coarse_dag_nodes"],
            serde_json::json!(["CoarseA", "CoarseB"])
        );
        assert_eq!(
            acceptance.current_paper_approved_fingerprints,
            BTreeMap::from([(
                TargetId::from("target_main"),
                "paper-approved-fp".to_string(),
            )])
        );
    }

