        #[test]
        fn isabelle_identity_axes_each_move_independently() {
            // Each axis must respond to ITS OWN input, or it is decoration.
            let dir = tempdir().expect("tempdir");
            let repo = dir.path();
            seed_isabelle_repo(repo);
            let home_dir = tempdir().expect("tempdir");
            let home = home_dir.path();
            seed_isabelle_home(home, "89701cf1768e", "Isabelle2025-2");
            let base = closure_identity_inputs_at(repo, Some(home));

            // A different Isabelle distribution.
            seed_isabelle_home(home, "ffffffffffff", "Isabelle2025-2");
            let other_dist = closure_identity_inputs_at(repo, Some(home));
            assert_ne!(
                base.toolchain_hash, other_dist.toolchain_hash,
                "a different distribution changeset must change the toolchain axis"
            );

            // A different parent session / heap pin.
            seed_isabelle_home(home, "89701cf1768e", "Isabelle2025-2");
            fs::write(repo.join("isabelle/ROOT"), "session Tablet = HOL +\n")
                .expect("rewrite ROOT");
            let other_root = closure_identity_inputs_at(repo, Some(home));
            assert_ne!(
                base.manifest_hash, other_root.manifest_hash,
                "a different session/heap pin must change the manifest axis"
            );

            // A different preamble import surface.
            fs::write(
                repo.join("Tablet/Preamble.thy"),
                "theory Tablet_Preamble\n  imports Complex_Main\nbegin\n\nend\n",
            )
            .expect("rewrite preamble");
            let other_pre = closure_identity_inputs_at(repo, Some(home));
            assert_ne!(
                base.preamble_hash, other_pre.preamble_hash,
                "a different preamble must change the preamble axis"
            );
        }

        #[test]
        fn isabelle_record_with_vacuous_identity_fails_closed() {
            // THE regression. Every one of the 18 live conn-isa records looked
            // like this: empty toolchain / manifest / preamble. Before the fix
            // the validator recomputed the LEAN paths — absent on an Isabelle
            // repo, so also empty — and "" == "" accepted the record, making
            // the cached acceptance independent of the toolchain, the session
            // pin and the preamble. It must now be a MISS.
            let dir = tempdir().expect("tempdir");
            let repo = dir.path();
            seed_isabelle_repo(repo);
            let state = ProtocolState::default();
            let mut record = LocalClosureRecord::default();
            record.node = NodeId::from("Foo");
            record.closure_version = CLOSURE_VERSION.to_string();
            record.toolchain_hash = String::new();
            record.lake_manifest_hash = String::new();
            record.preamble_hash = String::new();

            assert!(
                !record_hashes_match_current(&record, repo, &state),
                "a record whose identity axes pin nothing must not validate"
            );
        }

        #[test]
        fn isabelle_statement_hash_is_type_sensitive() {
            // The headline property, at the Rust layer: a type-carrier
            // generalization is a statement edit. Before the fix this function
            // ran the LEAN declaration parser over a `.thy`, found nothing, and
            // returned "" for both — which is why 10 of 18 live records carried
            // no statement axis at all.
            let dir = tempdir().expect("tempdir");
            let repo = dir.path();
            seed_isabelle_repo(repo);
            let thy = |ty: &str| {
                format!(
                    "theory Foo\n  imports Tablet_Preamble\nbegin\n\n\
                     theorem Foo:\n  fixes R :: \"{ty} \\<Rightarrow> {ty} \\<Rightarrow> bool\"\n  \
                     shows \"True\"\n  by simp\n\nend\n"
                )
            };

            fs::write(repo.join("Tablet/Foo.thy"), thy("nat")).expect("write nat");
            let nat_hash = active_statement_hash_for_node(repo, "Foo");
            fs::write(repo.join("Tablet/Foo.thy"), thy("'a")).expect("write 'a");
            let poly_hash = active_statement_hash_for_node(repo, "Foo");

            assert!(!nat_hash.is_empty(), "Isabelle statement axis must exist");
            assert!(!poly_hash.is_empty(), "Isabelle statement axis must exist");
            assert_ne!(
                nat_hash, poly_hash,
                "nat ⇒ 'a is a statement edit and must move the statement hash"
            );
        }

