        fn migration_probe(
            repo: &Path,
            node: &str,
            kind: NodeKind,
            open: bool,
        ) -> LocalClosureProbeOutput {
            let source = fs::read(repo.join("Tablet").join(format!("{node}.lean")))
                .expect("read migration source");
            let olean_path = repo
                .join(".lake/build/lib/lean/Tablet")
                .join(format!("{node}.olean"));
            fs::create_dir_all(olean_path.parent().expect("olean parent"))
                .expect("create migration olean tree");
            let olean = format!("migration-test-olean:{node}").into_bytes();
            fs::write(&olean_path, &olean).expect("write migration olean");
            let (principal_declaration, declaration_manifest) = if kind == NodeKind::Preamble {
                (String::new(), Vec::new())
            } else {
                (
                    node.to_string(),
                    vec![trellis_kernel::DeclarationManifestEntry {
                        name: node.to_string(),
                        kind: match kind {
                            NodeKind::Definition => "definition",
                            _ => "theorem",
                        }
                        .to_string(),
                    }],
                )
            };
            LocalClosureProbeOutput {
                status: "ok".to_string(),
                kernel_axioms: open
                    .then(|| BTreeSet::from(["sorryAx".to_string()]))
                    .unwrap_or_default(),
                principal_declaration,
                declaration_manifest: declaration_manifest.clone(),
                replay_declaration_manifest: declaration_manifest.clone(),
                direct_imports: Some(if kind == NodeKind::Preamble {
                    BTreeSet::new()
                } else {
                    BTreeSet::from(["Tablet.Preamble".to_string()])
                }),
                visibility_manifests: vec![trellis_kernel::VisibilityManifest {
                    level: "exported".to_string(),
                    declarations: declaration_manifest,
                }],
                artifact_bundle: vec![trellis_kernel::ArtifactBundlePart {
                    level: "exported".to_string(),
                    sha256: trellis_kernel::trust_base::raw_sha256(&olean),
                    size_bytes: olean.len() as u64,
                }],
                source_sha256: trellis_kernel::trust_base::raw_sha256(&source).to_string(),
                olean_sha256: trellis_kernel::trust_base::raw_sha256(&olean).to_string(),
                axiomization_check: Some(AxiomizationCheckOutput {
                    agreed: true,
                    skipped: false,
                    ..AxiomizationCheckOutput::default()
                }),
                ..LocalClosureProbeOutput::default()
            }
        }

        fn reverse_invalidation_chain_probe(repo: &Path, node: &str) -> LocalClosureProbeOutput {
            let kind = if node == "Preamble" {
                NodeKind::Preamble
            } else {
                NodeKind::Proof
            };
            let mut probe = migration_probe(repo, node, kind, false);
            let dependency = match node {
                "B" => Some("A"),
                "C" => Some("B"),
                _ => None,
            };
            if let Some(dependency) = dependency {
                probe.direct_imports = Some(BTreeSet::from([
                    format!("Tablet.{dependency}"),
                    "Tablet.Preamble".to_string(),
                ]));
                probe.exact_declaration_uses = vec![trellis_kernel::ObservedDeclarationUse {
                    owner: NodeId::from(dependency),
                    reached_declaration: dependency.to_string(),
                    declaration_kind: "theorem".to_string(),
                    visibility: "exported".to_string(),
                }];
            }
            probe
        }

        fn reverse_invalidation_chain_state(repo: &Path) -> ProtocolState {
            seed_repo(repo);
            fs::write(
                repo.join("Tablet/A.lean"),
                "import Tablet.Preamble\ntheorem A : True := by trivial\n",
            )
            .expect("write A v1");
            fs::write(
                repo.join("Tablet/B.lean"),
                "import Tablet.A\ntheorem B : True := by exact A\n",
            )
            .expect("write B");
            fs::write(
                repo.join("Tablet/C.lean"),
                "import Tablet.B\ntheorem C : True := by exact B\n",
            )
            .expect("write C");
            let mut state = ProtocolState::default();
            for (name, kind) in [
                ("Preamble", NodeKind::Preamble),
                ("A", NodeKind::Proof),
                ("B", NodeKind::Proof),
                ("C", NodeKind::Proof),
            ] {
                let node = NodeId::from(name);
                state.live.present_nodes.insert(node.clone());
                state.node_kinds.insert(node.clone(), kind);
                state
                    .live
                    .corr_current_fingerprints
                    .insert(node.clone(), format!("semantic:{name}"));
                if kind == NodeKind::Proof {
                    state.proof_nodes.insert(node);
                }
            }
            let owners = state.live.present_nodes.clone();
            ScheduledLocalClosureIssuer::mint_exact_set_with_probe(
                &mut state,
                repo,
                &owners,
                1,
                "reverse_invalidation_fixture",
                |repo, node, _timeout| Ok(reverse_invalidation_chain_probe(repo, node)),
            )
            .expect("mint initial chain");
            state.committed = state.live.clone();
            state.committed_node_kinds = state.node_kinds.clone();
            state.committed_proof_nodes = state.proof_nodes.clone();
            state.committed_local_closure_records = state.local_closure_records.clone();
            state
                .validate_local_closure_root_consistency()
                .expect("initial chain is root-current");
            state
        }

        /// The live cycle-66 / r204 halt shape (kernel
        /// regression from the certificate-v2 restructuring): a
        /// reviewer-directed cleanup burst inlines a wrapper lemma into its
        /// sole consumer and deletes the wrapper. `must_close_active=false`
        /// plus the deleted active node mean the burst carries ZERO probe
        /// results, while the delta touches nodes with closure-record
        /// consumers — a chain of depth 2: deleting A conservatively
        /// invalidates its record-consumer B, and B's own content edit
        /// invalidates B's record-consumer C. The engine's accept-time
        /// `formalization_valid` preflight then measures the record tier
        /// mid-repair, disagrees with the checker's contract/validation
        /// proxy, and the fail-loud seam halts the run. The restored
        /// pre-accept revalidation (`cleanup_pre_accept_revalidation_batch`)
        /// must re-certify exactly the newly-invalidated consumers so the
        /// same zero-probe burst is accepted with fresh records minted
        /// before the preflight — agreement through correct inputs, not a
        /// relaxed check.
        #[test]
        fn zero_probe_cleanup_burst_touching_record_consumers_is_accepted_with_pre_preflight_records(
        ) {
            let dir = tempdir().expect("tempdir");
            let repo = dir.path();
            let mut state = reverse_invalidation_chain_state(repo);
            state.phase = Phase::Cleanup;
            state.stage = trellis_kernel::model::Stage::Worker;
            state.cycle = 66;
            assert!(
                state.formalization_valid(),
                "fixture baseline must be formalization-valid"
            );
            let mut request = state.issue_request(RequestKind::Worker);
            request.worker_context.validation_kind = WorkerValidationKind::Cleanup;
            state.in_flight_request = Some(Box::new(request.clone()));

            // The reviewer-directed simplification, already applied to the
            // repo worktree at dispatch-return time: inline A into B, then
            // delete the now-unreferenced A.
            fs::write(
                repo.join("Tablet/B.lean"),
                "import Tablet.Preamble\ntheorem B : True := by exact True.intro\n",
            )
            .expect("inline A into B");
            fs::remove_file(repo.join("Tablet/A.lean")).expect("delete A");

            let a = NodeId::from("A");
            let b = NodeId::from("B");
            let c = NodeId::from("C");
            let mut snapshot = state.live.clone();
            snapshot.present_nodes.remove(&a);
            snapshot.open_nodes.remove(&a);
            snapshot.corr_current_fingerprints.remove(&a);
            snapshot
                .corr_current_fingerprints
                .insert(b.clone(), "semantic:B-v2".to_string());

            // The checker's shared preflight, computed from its proxy
            // inputs (contracts and validation steps all passed).
            let checker_preflight =
                trellis_kernel::worker_transition::evaluate_cleanup_transition_preflight(
                    trellis_kernel::worker_transition::CleanupTransitionPreflightInput {
                        enforce_formalization_validity: true,
                        baseline_formalization_valid: true,
                        post_formalization_valid: true,
                        baseline_live_orphans: state.orphan_nodes(&state.live),
                        post_live_orphans: state.orphan_nodes(&snapshot),
                    },
                );
            assert!(checker_preflight.accepted(), "checker proxy accepts r204");
            let response = WorkerResponse {
                request_id: request.id,
                cycle: 66,
                status: ResponseStatus::Ok,
                outcome: WorkerOutcome::Valid,
                snapshot,
                acceptance_check_passed: true,
                cleanup_transition_preflight: Some(checker_preflight),
                ..WorkerResponse::default()
            };
            assert!(
                response.local_closure_results.is_empty(),
                "the r204 shape carries zero probes"
            );

            // Bug shape: without pre-accept revalidation the engine
            // measures the conservatively-invalidated record tier before
            // anything repairs it, rejects the checker-accepted response,
            // and orders the restore — the engine half of the fail-loud
            // disagreement halt.
            let unrepaired = trellis_kernel::apply_event(
                state.clone(),
                ProtocolEvent::WrapperResponse {
                    response: WrapperResponse::Worker(response.clone()),
                },
            )
            .expect("engine rejection is a transition, not an error");
            assert!(
                unrepaired.commands.iter().any(|command| matches!(
                    command,
                    trellis_kernel::ProtocolCommand::RestoreWorktreeToActiveWorkerBase
                )),
                "without the pre-accept batch the engine must reject (this leg \
                 documents the halt the fix removes); commands: {:?}",
                unrepaired.commands
            );

            // The fix: the issuance adapter attaches the pre-accept batch
            // for exactly the newly-invalidated consumers.
            let mut repaired_response = response;
            let batch = crate::cleanup_pre_accept_revalidation_batch_with_probe(
                &state,
                &repaired_response,
                repo,
                66,
                |repo, node, _timeout| match node {
                    "B" => Ok(migration_probe(repo, "B", NodeKind::Proof, false)),
                    "C" => Ok(reverse_invalidation_chain_probe(repo, node)),
                    other => panic!("unexpected probe for {other}"),
                },
            )
            .expect("the worktree holds this response's delta");
            let refreshed: BTreeSet<NodeId> = batch
                .refreshed
                .iter()
                .map(|(node, _)| node.clone())
                .collect();
            assert_eq!(
                refreshed,
                BTreeSet::from([b.clone(), c.clone()]),
                "the depth-2 consumer chain is reminted pre-accept; batch: {batch:?}"
            );
            assert!(
                batch.still_unverified.is_empty(),
                "no failures expected: {batch:?}"
            );
            let shared = std::rc::Rc::new(std::cell::RefCell::new(None));
            crate::merge_revalidation_batch(&mut repaired_response, &shared, batch);

            let outcome = trellis_kernel::apply_event(
                state,
                ProtocolEvent::WrapperResponse {
                    response: WrapperResponse::Worker(repaired_response),
                },
            )
            .expect("repaired cleanup acceptance applies");
            assert!(
                !outcome.commands.iter().any(|command| matches!(
                    command,
                    trellis_kernel::ProtocolCommand::RestoreWorktreeToActiveWorkerBase
                )),
                "the zero-probe cleanup burst must be ACCEPTED once consumers are \
                 re-certified pre-preflight; commands: {:?}",
                outcome.commands
            );
            let post = &outcome.state;
            assert!(
                post.formalization_valid(),
                "post-accept validity holds because the inputs are repaired, \
                 not because the preflight was weakened"
            );
            for node in [&b, &c] {
                let record = post
                    .local_closure_records
                    .get(node)
                    .unwrap_or_else(|| panic!("{node} must hold a fresh record"));
                assert!(
                    record_hashes_match_current(record, repo, post),
                    "{node}'s reminted record must describe the accepted source"
                );
            }
            assert!(
                !post.local_closure_unverified_nodes.contains(&b)
                    && !post.local_closure_unverified_nodes.contains(&c),
                "consumers must not remain unverified after acceptance"
            );
            assert!(
                !post.live.present_nodes.contains(&a),
                "the reviewer-directed deletion is kept"
            );
        }

        /// The live cycle-66 RE-halt, ten minutes after the
        /// pre-accept fix was deployed: same request, same rejection text.
        ///
        /// The burst response was not regenerated — the bridge replayed the
        /// persisted `bridge/latest_worker.json` verbatim
        /// (the historical cache matched only
        /// `(kind, request_id, cycle)`) — while
        /// the operator had restored the worktree to `active_worker_base`
        /// first. So a POST-delta response met a PRE-delta worktree:
        /// `StrictSpanGrowth.lean` was back on disk and
        /// `DStarMarkedTreeBound.lean` imported it again, while the response
        /// reported `StrictSpanGrowth` deleted.
        ///
        /// Probing that pair is worse than useless. The probe truthfully
        /// reports the pre-delta source, whose declaration uses name an owner
        /// the response reports deleted; the probe validator rejects it as
        /// "owner absent"; every consumer lands in `still_unverified`; and the
        /// engine preflight then blames the WORKER for regressing
        /// `formalization_valid` through the checker/engine disagreement seam —
        /// after burning the full probe budget (623.7s live).
        ///
        /// A stale replay is an environment fault. It must be refused by name,
        /// before probing, and it must not reach the soundness seam.
        #[test]
        fn replayed_response_whose_delta_is_absent_from_the_worktree_is_refused_before_probing() {
            let dir = tempdir().expect("tempdir");
            let repo = dir.path();
            let mut state = reverse_invalidation_chain_state(repo);
            state.phase = Phase::Cleanup;
            state.stage = trellis_kernel::model::Stage::Worker;
            state.cycle = 66;
            let mut request = state.issue_request(RequestKind::Worker);
            request.worker_context.validation_kind = WorkerValidationKind::Cleanup;

            let a = NodeId::from("A");
            let mut snapshot = state.live.clone();
            snapshot.present_nodes.remove(&a);
            snapshot.open_nodes.remove(&a);
            snapshot.corr_current_fingerprints.remove(&a);
            snapshot
                .corr_current_fingerprints
                .insert(NodeId::from("B"), "semantic:B-v2".to_string());
            let response = WorkerResponse {
                request_id: request.id,
                cycle: 66,
                status: ResponseStatus::Ok,
                outcome: WorkerOutcome::Valid,
                snapshot,
                acceptance_check_passed: true,
                ..WorkerResponse::default()
            };

            // The restored worktree: A's source is back on disk, exactly as
            // `active_worker_base` left it, contradicting the replayed response.
            assert!(
                repo.join("Tablet/A.lean").exists(),
                "fixture must reproduce the restored pre-delta worktree"
            );

            let error = crate::cleanup_pre_accept_revalidation_batch_with_probe(
                &state,
                &response,
                repo,
                66,
                |_repo, node, _timeout| {
                    panic!(
                        "the guard must refuse BEFORE probing; probed {node} against a \
                         worktree that does not hold this response's delta"
                    )
                },
            )
            .expect_err("a response whose delta is absent from the worktree must be refused");
            assert!(
                error.contains("A: response reports it deleted, but Tablet/A.lean is present on disk"),
                "the refusal must name the exact divergence: {error}"
            );
            assert!(
                error.contains("latest_worker.json"),
                "the refusal must name what to discard to re-dispatch: {error}"
            );

            // Same response, same state, against the worktree the response
            // actually describes: the guard passes and certification proceeds.
            fs::remove_file(repo.join("Tablet/A.lean")).expect("apply the delta to the worktree");
            fs::write(
                repo.join("Tablet/B.lean"),
                "import Tablet.Preamble\ntheorem B : True := by exact True.intro\n",
            )
            .expect("inline A into B");
            let batch = crate::cleanup_pre_accept_revalidation_batch_with_probe(
                &state,
                &response,
                repo,
                66,
                |repo, node, _timeout| match node {
                    "B" => Ok(migration_probe(repo, "B", NodeKind::Proof, false)),
                    "C" => Ok(reverse_invalidation_chain_probe(repo, node)),
                    other => panic!("unexpected probe for {other}"),
                },
            )
            .expect("the same response is certifiable once the worktree holds its delta");
            assert_eq!(
                batch
                    .refreshed
                    .iter()
                    .map(|(node, _)| node.clone())
                    .collect::<BTreeSet<NodeId>>(),
                BTreeSet::from([NodeId::from("B"), NodeId::from("C")]),
                "the guard must not suppress a legitimate pre-accept mint: {batch:?}"
            );
        }


        /// The live cycle-48/49 failure shape: an accepted
        /// standard worker burst improves an open proof node's body on disk
        /// while the statement stays protected and byte-identical, the node
        /// stays open, and no record was installed same-burst.  Every
        /// pure-state projection is unchanged, so before the disk arm of
        /// `apply_roots` the acceptance derived zero roots, the node's stale
        /// record survived the scoped invalidation, and the next Worker
        /// dispatch's global certificate-artifact-epoch audit killed the
        /// supervisor.  The apply itself must remint the touched owner and
        /// its transitive certificate consumers.
        #[test]
        fn worker_partial_progress_with_no_projection_delta_remints_touched_owner() {
            let dir = tempdir().expect("tempdir");
            let repo = dir.path();
            let mut pre = reverse_invalidation_chain_state(repo);
            let a = NodeId::from("A");
            // The node under work is open with a truthful sorryAx closure —
            // in pre AND post, so openness contributes no projection delta.
            pre.live.open_nodes.insert(a.clone());
            pre.committed.open_nodes.insert(a.clone());

            // The accepted burst's authoritative source apply: partial
            // progress on A's proof body only.  No presence, openness, kind,
            // fingerprint, or record delta accompanies it.
            fs::write(
                repo.join("Tablet/A.lean"),
                "import Tablet.Preamble\ntheorem A : True := by\n  have h : True := by sorry\n  exact h\n",
            )
            .expect("write A partial-progress body");
            let mut post = pre.clone();
            assert!(
                !record_hashes_match_current(&post.local_closure_records[&a], repo, &post),
                "fixture must reproduce the stale retained record"
            );

            let event = ProtocolEvent::WrapperResponse {
                response: WrapperResponse::Worker(WorkerResponse::default()),
            };
            let probed = std::sync::Mutex::new(BTreeSet::new());
            ScheduledLocalClosureIssuer::reconcile_authoritative_source_apply_with_probe(
                &pre,
                &mut post,
                repo,
                &event,
                &[],
                |repo, node, _timeout| {
                    probed
                        .lock()
                        .expect("probe log lock")
                        .insert(node.to_string());
                    let mut probe = reverse_invalidation_chain_probe(repo, node);
                    if node == "A" {
                        probe.kernel_axioms.insert("sorryAx".to_string());
                    }
                    Ok(probe)
                },
            )
            .expect("acceptance must reconcile the source bytes it landed");
            assert_eq!(
                *probed.lock().expect("probe log lock"),
                BTreeSet::from(["A".to_string(), "B".to_string(), "C".to_string()]),
                "the touched owner and its transitive certificate consumers must be reminted"
            );
            let record = &post.local_closure_records[&a];
            assert!(
                record_hashes_match_current(record, repo, &post),
                "A's record must describe the accepted partial-progress source"
            );
            assert!(
                record.kernel_axioms.contains("sorryAx"),
                "the reminted open-owner record stays truthful about the remaining sorry"
            );
            post.validate_local_closure_root_consistency()
                .expect("no consumer may pin the superseded certificate root");
        }

        #[test]
        fn rollback_record_mirroring_is_source_and_dependency_closed() {
            let dir = tempdir().expect("tempdir");
            let repo = dir.path();
            let mut state = reverse_invalidation_chain_state(repo);
            let a = NodeId::from("A");
            let b = NodeId::from("B");
            let c = NodeId::from("C");

            // This rollback source predates A. Even though B and C retain the
            // same semantic fingerprints, neither their live certificates nor
            // C's downstream certificate can be paired with that source.
            state.committed.present_nodes.remove(&a);
            state.committed_node_kinds.remove(&a);
            state.committed_local_closure_records.remove(&a);
            state.committed_local_closure_records.remove(&b);
            state.committed_local_closure_records.remove(&c);
            ScheduledLocalClosureIssuer::mirror_current_records_into_matching_snapshots(
                &mut state,
                &BTreeSet::from([b.clone(), c.clone()]),
            );
            assert!(!state.committed_local_closure_records.contains_key(&b));
            assert!(!state.committed_local_closure_records.contains_key(&c));

            // LastClean has A logically but its exact certificate source is
            // from the old proof body. The semantic fingerprint is unchanged;
            // exact source identity must still prevent mirroring.
            state.last_clean_local_closure_mirror_ready = true;
            state.last_clean_live = state.live.clone();
            state.last_clean_node_kinds = state.node_kinds.clone();
            state.last_clean_local_closure_records = state.local_closure_records.clone();
            let mut stale_a = state.last_clean_local_closure_records[&a].clone();
            stale_a
                .node_certificate
                .as_mut()
                .expect("A certificate")
                .source_sha256 = trellis_kernel::trust_base::Sha256Digest::default();
            state
                .last_clean_local_closure_records
                .insert(a.clone(), stale_a);
            state.last_clean_local_closure_records.remove(&b);
            state.last_clean_local_closure_records.remove(&c);
            ScheduledLocalClosureIssuer::mirror_current_records_into_matching_snapshots(
                &mut state,
                &BTreeSet::from([b.clone(), c.clone()]),
            );
            assert!(!state.last_clean_local_closure_records.contains_key(&b));
            assert!(!state.last_clean_local_closure_records.contains_key(&c));
        }

        /// The live cycle-69 / r212 crash shape (committed-tier
        /// mirror corruption): a cleanup burst edits ONLY the proof body of a
        /// certificate-holding node and carries same-burst closure evidence
        /// for exactly that node, so its fresh record (new certified root)
        /// lands in the LIVE tier at accept and the reconcile never schedules
        /// the owner. The owner's corr fingerprint / kind / open-flag are
        /// unchanged, so under the pre-fix committed candidacy filter (no
        /// source check) the owner stays a candidate, its record-holding
        /// consumers survive the dependency-closure guard, and the write
        /// loop — which writes only SCHEDULED nodes — mirrors the reminted
        /// consumers (pinning the new root) into a committed tier whose
        /// owner record still pins the old root. The reconcile-tail
        /// `validate_local_closure_root_consistency` then correctly rejects
        /// the corrupted rollback tier and the supervisor dies.
        ///
        /// The fix requires certificate-source agreement for committed
        /// candidacy WHEN a committed record exists (missing records stay
        /// eligible: legacy/new-node seeding). The owner then drops from
        /// candidacy, the guard drops its consumer cone, nothing is
        /// mirrored, and committed keeps its coherent pre-burst pair —
        /// `commit_live` refreshes it wholesale at the next boundary.
        #[test]
        fn proof_body_edit_with_same_burst_evidence_keeps_committed_tier_coherent() {
            let dir = tempdir().expect("tempdir");
            let repo = dir.path();
            let pre = reverse_invalidation_chain_state(repo);
            let a = NodeId::from("A");
            let b = NodeId::from("B");
            let c = NodeId::from("C");

            // The accepted cleanup burst: proof-body-only edit of A. No
            // presence, openness, kind, or fingerprint delta.
            fs::write(
                repo.join("Tablet/A.lean"),
                "import Tablet.Preamble\ntheorem A : True := by\n  exact True.intro\n",
            )
            .expect("write A proof-body edit");

            // Same-burst closure evidence for exactly {A}: the engine
            // installs the fresh record into the LIVE tier only
            // (`apply_revalidation_batch_with_exclusions` writes
            // `local_closure_records` exclusively). Mint against the edited
            // source in a scratch state and transplant only the live record,
            // so the committed tier stays exactly as accept left it.
            let mut post = pre.clone();
            let mut scratch = pre.clone();
            ScheduledLocalClosureIssuer::mint_exact_set_with_probe(
                &mut scratch,
                repo,
                &BTreeSet::from([a.clone()]),
                1,
                "same_burst_evidence_fixture",
                |repo, node, _timeout| Ok(reverse_invalidation_chain_probe(repo, node)),
            )
            .expect("mint same-burst evidence for A");
            let fresh_a = scratch.local_closure_records[&a].clone();
            assert_ne!(
                fresh_a.node_certificate.as_ref().unwrap().certified_node_root,
                pre.local_closure_records[&a]
                    .node_certificate
                    .as_ref()
                    .unwrap()
                    .certified_node_root,
                "fixture must reproduce the pre->post root delta on the owner"
            );
            post.local_closure_records.insert(a.clone(), fresh_a);

            let event = ProtocolEvent::WrapperResponse {
                response: WrapperResponse::Worker(WorkerResponse::default()),
            };
            let probed = std::sync::Mutex::new(BTreeSet::new());
            ScheduledLocalClosureIssuer::reconcile_authoritative_source_apply_with_probe(
                &pre,
                &mut post,
                repo,
                &event,
                &[],
                |repo, node, _timeout| {
                    probed
                        .lock()
                        .expect("probe log lock")
                        .insert(node.to_string());
                    Ok(reverse_invalidation_chain_probe(repo, node))
                },
            )
            .expect(
                "the reconcile must not corrupt the committed rollback tier \
                 (pre-fix: committed consumer records were reminted against a \
                 root the tier's owner record does not hold)",
            );

            // The owner arrived current via same-burst evidence; only its
            // transitive consumer cone is scheduled (loop 2).
            assert_eq!(
                *probed.lock().expect("probe log lock"),
                BTreeSet::from(["B".to_string(), "C".to_string()]),
                "reverse-root-delta must remint exactly the consumer cone"
            );

            // LIVE tier: coherent at the new root, records current on disk.
            post.validate_local_closure_root_consistency()
                .expect("both tiers must be internally root-coherent");
            for node in [&a, &b, &c] {
                assert!(
                    record_hashes_match_current(&post.local_closure_records[node], repo, &post),
                    "live record for {} must describe the accepted source",
                    node.as_str()
                );
            }
            assert_eq!(
                post.local_closure_records[&b]
                    .node_certificate
                    .as_ref()
                    .unwrap()
                    .dependency_certificate_roots[&a],
                post.local_closure_records[&a]
                    .node_certificate
                    .as_ref()
                    .unwrap()
                    .certified_node_root,
                "live consumer must pin the owner's NEW root"
            );

            // COMMITTED tier: byte-identical to its coherent pre-burst pair.
            // Mirroring the consumers (the pre-fix write) is wrong for this
            // tier — its rollback source holds pre-edit owner bytes — and
            // mirroring the owner instead would corrupt it more deeply.
            assert_eq!(
                post.committed_local_closure_records, pre.committed_local_closure_records,
                "committed rollback tier must keep its coherent pre-burst records"
            );
        }

        fn rollback_mirroring_chain_state(repo: &Path) -> ProtocolState {
            let mut state = reverse_invalidation_chain_state(repo);
            state.last_clean_local_closure_mirror_ready = true;
            state.last_clean_live = state.live.clone();
            state.last_clean_node_kinds = state.node_kinds.clone();
            state.last_clean_proof_nodes = state.proof_nodes.clone();
            state.last_clean_local_closure_records = state.local_closure_records.clone();
            state
        }

        #[test]
        fn rollback_mirroring_checks_actual_write_set_to_fixed_point() {
            let dir = tempdir().expect("tempdir");
            let pre = rollback_mirroring_chain_state(dir.path());
            let chain = [NodeId::from("A"), NodeId::from("B"), NodeId::from("C")];
            // Model a coherent root refresh without changing owner sources.
            // Every proper nonempty write subset would mix old and new roots.
            for first_changed in 0..2 {
                let mut refreshed = pre.local_closure_records.clone();
                for index in first_changed..chain.len() {
                    let certificate = refreshed
                        .get_mut(&chain[index])
                        .unwrap()
                        .node_certificate
                        .as_mut()
                        .unwrap();
                    certificate.certified_node_root = trellis_kernel::trust_base::raw_sha256(
                        format!("refreshed-root-{index}").as_bytes(),
                    );
                    if index > first_changed {
                        certificate.dependency_certificate_roots.insert(
                            chain[index - 1].clone(),
                            trellis_kernel::trust_base::raw_sha256(
                                format!("refreshed-root-{}", index - 1).as_bytes(),
                            ),
                        );
                    }
                }
                for mask in 0..8 {
                    let mut state = pre.clone();
                    state.local_closure_records = refreshed.clone();
                    state.validate_local_closure_root_consistency().unwrap();
                    let writes = chain
                        .iter()
                        .enumerate()
                        .filter(|(index, _)| mask & (1 << index) != 0)
                        .map(|(_, node)| node.clone())
                        .collect();
                    ScheduledLocalClosureIssuer::mirror_current_records_into_matching_snapshots(
                        &mut state, &writes,
                    );
                    state.validate_local_closure_root_consistency().unwrap();
                    let complete = (first_changed..chain.len()).all(|index| mask & (1 << index) != 0);
                    for node in &chain {
                        let expected = if complete {
                            &refreshed[node]
                        } else {
                            &pre.local_closure_records[node]
                        };
                        assert_eq!(
                            &state.committed_local_closure_records[node], expected,
                            "committed: first={first_changed}, mask={mask}"
                        );
                        assert_eq!(
                            &state.last_clean_local_closure_records[node], expected,
                            "LastClean: first={first_changed}, mask={mask}"
                        );
                    }
                }
            }
        }

        #[test]
        fn global_worker_preamble_and_consumer_edit_preserves_rollback() {
            let dir = tempdir().expect("tempdir");
            let repo = dir.path();
            let mut pre = reverse_invalidation_chain_state(repo);
            pre.phase = Phase::TheoremStating;
            pre.target_edit_mode = trellis_kernel::model::TargetEditMode::Global;
            pre.stage = trellis_kernel::model::Stage::Worker;
            pre.ensure_node_metadata();
            assert_eq!(
                pre.current_worker_validation_kind(),
                WorkerValidationKind::TheoremGlobal
            );
            let plan = pre.current_worker_validation_execution_plan();
            assert!(matches!(
                plan.as_slice(),
                [
                    trellis_kernel::model::WorkerValidationExecutionPlanStep::ScopedTablet {
                        allowed_nodes_mode: trellis_kernel::model::ScopedTabletAllowedNodesMode::AllPresent,
                        ..
                    }
                ]
            ));
            let request = pre.issue_request(RequestKind::Worker);
            pre.in_flight_request = Some(Box::new(request.clone()));
            pre.validate()
                .expect("the fresh pre-worker state must be valid");
            fs::write(
                repo.join("Tablet/Preamble.lean"),
                "-- preamble\n-- formatting comment\n",
            )
            .unwrap();
            fs::write(
                repo.join("Tablet/C.lean"),
                "import Tablet.B\ntheorem C : True := by\n  exact B\n",
            )
            .unwrap();
            let mut snapshot = pre.live.clone();
            snapshot
                .corr_current_fingerprints
                .insert(NodeId::from("Preamble"), "semantic:Preamble-v2".into());
            let event = ProtocolEvent::WrapperResponse {
                response: WrapperResponse::Worker(WorkerResponse {
                    request_id: request.id,
                    cycle: pre.cycle,
                    status: ResponseStatus::Ok,
                    outcome: WorkerOutcome::Valid,
                    acceptance_check_passed: true,
                    snapshot,
                    ..WorkerResponse::default()
                }),
            };
            let outcome = trellis_kernel::engine::apply_event(pre.clone(), event.clone())
                .expect("global worker transition");
            let mut post = outcome.state;
            let result = ScheduledLocalClosureIssuer::reconcile_authoritative_source_apply_with_probe(
                &pre,
                &mut post,
                repo,
                &event,
                &outcome.commands,
                |repo, node, _| Ok(reverse_invalidation_chain_probe(repo, node)),
            );
            result.expect("global worker source update must preserve rollback root consistency");
            post.validate_local_closure_root_consistency().unwrap();
            for node in [NodeId::from("A"), NodeId::from("B"), NodeId::from("C")] {
                assert_eq!(
                    post.committed_local_closure_records[&node],
                    pre.committed_local_closure_records[&node]
                );
                assert!(record_hashes_match_current(
                    &post.local_closure_records[&node],
                    repo,
                    &post
                ));
            }
        }

