        #[test]
        fn scheduled_initial_issuance_mints_proof_definition_preamble_and_open_proof() {
            let dir = tempdir().expect("tempdir");
            seed_repo(dir.path());
            let mut state = ProtocolState::default();
            for (name, kind, open) in [
                ("ProofOwner", NodeKind::Proof, false),
                ("OpenProofOwner", NodeKind::Proof, true),
                ("DefinitionOwner", NodeKind::Definition, false),
                ("Preamble", NodeKind::Preamble, false),
            ] {
                let node = NodeId::from(name);
                state.live.present_nodes.insert(node.clone());
                state.node_kinds.insert(node.clone(), kind);
                state
                    .live
                    .corr_current_fingerprints
                    .insert(node.clone(), format!("semantic:{name}"));
                if kind == NodeKind::Proof {
                    state.proof_nodes.insert(node.clone());
                }
                if open {
                    state.live.open_nodes.insert(node);
                }
                if name != "Preamble" {
                    let declaration = match kind {
                        NodeKind::Definition => format!("def {name} : Nat := 0"),
                        _ if open => format!("theorem {name} : True := by sorry"),
                        _ => format!("theorem {name} : True := by trivial"),
                    };
                    fs::write(
                        dir.path().join("Tablet").join(format!("{name}.lean")),
                        format!("import Tablet.Preamble\n{declaration}\n"),
                    )
                    .expect("write scheduled owner source");
                }
            }
            let expected = BTreeSet::from([
                NodeId::from("DefinitionOwner"),
                NodeId::from("OpenProofOwner"),
                NodeId::from("Preamble"),
                NodeId::from("ProofOwner"),
            ]);
            let scheduled = ScheduledLocalClosureIssuer::scheduled_nodes(
                &ProtocolState::default(),
                &state,
                dir.path(),
                &expected,
                "fresh_runtime_initial_issuance",
            )
            .expect("new owners are scheduled");
            assert_eq!(scheduled, expected);
            ScheduledLocalClosureIssuer::mint_exact_set_with_probe(
                &mut state,
                dir.path(),
                &scheduled,
                0,
                "fresh_runtime_initial_issuance",
                |repo, node, _timeout| {
                    let (kind, open) = match node {
                        "DefinitionOwner" => (NodeKind::Definition, false),
                        "Preamble" => (NodeKind::Preamble, false),
                        "OpenProofOwner" => (NodeKind::Proof, true),
                        _ => (NodeKind::Proof, false),
                    };
                    Ok(migration_probe(repo, node, kind, open))
                },
            )
            .expect("scheduled genesis issuance");
            assert_eq!(
                state.local_closure_records.keys().cloned().collect::<BTreeSet<_>>(),
                expected
            );
            assert!(state.local_closure_records[&NodeId::from("OpenProofOwner")]
                .kernel_axioms
                .contains("sorryAx"));
        }

        #[test]
        fn replay_installs_exact_scheduled_issuance_carrier_without_probing() {
            let owner = NodeId::from("ReplayDefinition");
            let mut state = ProtocolState::default();
            state.live.present_nodes.insert(owner.clone());
            state
                .node_kinds
                .insert(owner.clone(), NodeKind::Definition);
            state.local_closure_unverified_nodes.insert(owner.clone());
            let record = LocalClosureRecord {
                node: owner.clone(),
                closure_version: CLOSURE_VERSION.to_string(),
                toolchain_hash: "toolchain".to_string(),
                lean_executable_hash: "lean".to_string(),
                lake_executable_hash: "lake".to_string(),
                checker_script_hash: "checker".to_string(),
                lake_manifest_hash: "manifest".to_string(),
                preamble_hash: "preamble".to_string(),
                approved_axioms_hash: "axioms".to_string(),
                active_decl_hash: "decl".to_string(),
                active_statement_hash: "statement".to_string(),
                ..LocalClosureRecord::default()
            };
            let command = ProtocolCommand::InstallScheduledLocalClosureRecords {
                records: BTreeMap::from([(owner.clone(), record.clone())]),
            };
            apply_replayed_scheduled_local_closure_records(&mut state, &[command], 17)
                .expect("replay installs original issuance evidence");
            assert_eq!(state.local_closure_records.get(&owner), Some(&record));
            assert!(!state.local_closure_unverified_nodes.contains(&owner));

            let mismatched = ProtocolCommand::InstallScheduledLocalClosureRecords {
                records: BTreeMap::from([(
                    owner,
                    LocalClosureRecord {
                        node: NodeId::from("DifferentOwner"),
                        ..record
                    },
                )]),
            };
            let error = apply_replayed_scheduled_local_closure_records(
                &mut state,
                &[mismatched],
                18,
            )
            .expect_err("mismatched carrier identity must fail loud");
            assert!(error.contains("line 18"), "{error}");
            assert!(error.contains("DifferentOwner"), "{error}");
        }

        #[test]
        fn point_of_use_missing_is_fatal_but_stale_is_reprobe_work() {
            let dir = tempdir().expect("tempdir");
            fs::create_dir_all(dir.path().join("Tablet")).expect("Tablet");
            let node = NodeId::from("ExistingDefinition");
            let mut pre = ProtocolState::default();
            pre.live.present_nodes.insert(node.clone());
            pre.node_kinds.insert(node.clone(), NodeKind::Definition);
            let post = pre.clone();
            let missing = ScheduledLocalClosureIssuer::scheduled_nodes(
                &pre,
                &post,
                dir.path(),
                &BTreeSet::from([node.clone()]),
                "definition_worker_acceptance",
            )
            .expect_err("an unchanged preexisting gap is not issuance work");
            assert!(matches!(
                missing,
                trellis_kernel::RuntimeError::MissingLocalClosureRecord {
                    node: ref actual,
                    kind: NodeKind::Definition,
                    expected_apply_site: "definition_worker_acceptance",
                } if actual == &node
            ));

            let mut pre_with_record = pre;
            pre_with_record.local_closure_records.insert(
                node.clone(),
                LocalClosureRecord {
                    node: node.clone(),
                    closure_version: "retired".to_string(),
                    ..LocalClosureRecord::default()
                },
            );
            let stale = ScheduledLocalClosureIssuer::scheduled_nodes(
                &pre_with_record,
                &pre_with_record,
                dir.path(),
                &BTreeSet::from([node.clone()]),
                "definition_worker_acceptance",
            )
            .expect("point-of-use stale evidence is recoverable re-probe work");
            assert_eq!(stale, BTreeSet::from([node]));
        }

        #[test]
        fn unrelated_stale_owner_does_not_block_apply_but_cited_owner_is_reminted() {
            let dir = tempdir().expect("tempdir");
            let repo = dir.path();
            seed_repo(repo);
            for name in ["Boundary", "Target", "Unrelated"] {
                write_node(repo, name, "by trivial");
            }

            let mut state = ProtocolState::default();
            for name in ["Boundary", "Target", "Unrelated"] {
                let node = NodeId::from(name);
                state.live.present_nodes.insert(node.clone());
                state.proof_nodes.insert(node.clone());
                state.node_kinds.insert(node.clone(), NodeKind::Proof);
                state
                    .live
                    .corr_current_fingerprints
                    .insert(node.clone(), format!("semantic:{name}"));
                state.local_closure_unverified_nodes.insert(node);
            }

            let probe_for = |repo: &Path, name: &str| {
                let mut probe = migration_probe(repo, name, NodeKind::Proof, false);
                if name == "Target" {
                    probe.direct_imports = Some(BTreeSet::from([
                        "Tablet.Boundary".to_string(),
                        "Tablet.Preamble".to_string(),
                    ]));
                    probe.exact_declaration_uses = vec![
                        trellis_kernel::ObservedDeclarationUse {
                            owner: NodeId::from("Boundary"),
                            reached_declaration: "Boundary".to_string(),
                            declaration_kind: "theorem".to_string(),
                            visibility: "exported".to_string(),
                        },
                    ];
                }
                probe
            };
            let initial = deterministic_revalidate_at_cli_with_probe(
                &state,
                repo,
                1,
                |repo, name| Ok(probe_for(repo, name)),
            );
            assert!(initial.still_unverified.is_empty(), "{initial:?}");
            trellis_kernel::engine::apply_revalidation_batch(&mut state, initial);

            fs::write(
                repo.join(".lake/build/lib/lean/Tablet/Unrelated.olean"),
                b"transient unrelated rebuild bytes",
            )
            .expect("stale unrelated artifact");
            assert!(!record_hashes_match_current(
                &state.local_closure_records[&NodeId::from("Unrelated")],
                repo,
                &state,
            ));
            let event = trellis_kernel::ProtocolEvent::SidecarClosure {
                payload: trellis_kernel::SidecarClosurePayload {
                    node: NodeId::from("Target"),
                    ..trellis_kernel::SidecarClosurePayload::default()
                },
            };
            let target_root = ScheduledLocalClosureIssuer::apply_roots(
                &state,
                &state,
                repo,
                &event,
                &[],
            );
            assert_eq!(target_root, BTreeSet::from([NodeId::from("Target")]));
            let scheduled = ScheduledLocalClosureIssuer::scheduled_nodes(
                &state,
                &state,
                repo,
                &target_root,
                "sidecar_dispatch_apply",
            )
            .expect("unrelated artifact drift is outside this apply");
            assert!(scheduled.is_empty());

            // The same drift on an owner the target certificate actually
            // cites is point-of-use work.  Refresh the owner and the consumer
            // whose recursive root names it, then prove both are current.
            fs::write(
                repo.join(".lake/build/lib/lean/Tablet/Boundary.olean"),
                b"transient cited-owner rebuild bytes",
            )
            .expect("stale cited artifact");
            let scheduled = ScheduledLocalClosureIssuer::scheduled_nodes(
                &state,
                &state,
                repo,
                &target_root,
                "sidecar_dispatch_apply",
            )
            .expect("cited artifact drift is recoverable");
            assert_eq!(
                scheduled,
                BTreeSet::from([NodeId::from("Boundary"), NodeId::from("Target")])
            );
            ScheduledLocalClosureIssuer::mint_exact_set_with_probe(
                &mut state,
                repo,
                &scheduled,
                2,
                "sidecar_dispatch_apply",
                |repo, name, _timeout| Ok(probe_for(repo, name)),
            )
            .expect("point-of-use closure remints in dependency order");
            for node in &scheduled {
                assert!(record_hashes_match_current(
                    &state.local_closure_records[node],
                    repo,
                    &state,
                ));
            }
        }



        #[test]
        fn explicit_source_change_invalidation_reprobes_and_remints() {
            let dir = tempdir().expect("tempdir");
            let repo = dir.path();
            seed_repo(repo);
            let node = NodeId::from("MutableDefinition");
            fs::write(
                repo.join("Tablet/MutableDefinition.lean"),
                "import Tablet.Preamble\ndef MutableDefinition : Nat := 0\n",
            )
            .expect("write v1");
            let mut state = ProtocolState::default();
            state.live.present_nodes.insert(node.clone());
            state.node_kinds.insert(node.clone(), NodeKind::Definition);
            state
                .live
                .corr_current_fingerprints
                .insert(node.clone(), "semantic-v1".to_string());
            state.local_closure_unverified_nodes.insert(node.clone());

            let first = deterministic_revalidate_at_cli_with_probe(&state, repo, 1, |repo, _| {
                Ok(migration_probe(
                    repo,
                    node.as_str(),
                    NodeKind::Definition,
                    false,
                ))
            });
            trellis_kernel::engine::apply_revalidation_batch(&mut state, first);
            let old = state.local_closure_records[&node].clone();

            fs::write(
                repo.join("Tablet/MutableDefinition.lean"),
                "import Tablet.Preamble\ndef MutableDefinition : Nat := 1\n",
            )
            .expect("write v2");
            state
                .live
                .corr_current_fingerprints
                .insert(node.clone(), "semantic-v2".to_string());
            state.local_closure_records.remove(&node);
            state.local_closure_unverified_nodes.insert(node.clone());

            let second = deterministic_revalidate_at_cli_with_probe(&state, repo, 2, |repo, _| {
                Ok(migration_probe(
                    repo,
                    node.as_str(),
                    NodeKind::Definition,
                    false,
                ))
            });
            trellis_kernel::engine::apply_revalidation_batch(&mut state, second);
            let reminted = &state.local_closure_records[&node];
            assert_ne!(old.active_decl_hash, reminted.active_decl_hash);
            assert_ne!(
                old.node_certificate
                    .as_ref()
                    .expect("old certificate")
                    .certified_node_root,
                reminted
                    .node_certificate
                    .as_ref()
                    .expect("new certificate")
                    .certified_node_root
            );
            assert!(record_hashes_match_current(reminted, repo, &state));
        }

        #[test]
        fn cleanup_revalidation_adapter_passes_non_cleanup_through() {
            // The wrapper must not modify non-cleanup responses.
            let dir = tempdir().expect("tempdir");
            let repo = dir.path();
            seed_repo(repo);
            let mut state = ProtocolState::default();
            state
                .local_closure_unverified_nodes
                .insert(NodeId::from("Foo"));
            let worker_response = trellis_kernel::WorkerResponse::default();
            let responses = vec![WrapperResponse::Worker(worker_response)];
            let inner = StubAdapter { responses };
            let _runtime_root = tempdir().expect("runtime root");
            let shared: std::rc::Rc<std::cell::RefCell<Option<RevalidationBatch>>> =
                std::rc::Rc::new(std::cell::RefCell::new(None));
            let mut wrapper = ScheduledWorkerIssuanceAdapter {
                inner,
                state: &state,
                repo: repo.to_path_buf(),
                current_cycle: 9,
                shared_batch: shared.clone(),
            };
            let mut request = WrapperRequest::default();
            request.kind = RequestKind::Worker;
            request.worker_context.validation_kind = WorkerValidationKind::ProofLocal;
            let response = wrapper.dispatch(&request).expect("dispatch");
            let WrapperResponse::Worker(worker) = response else {
                panic!("expected Worker response");
            };
            assert!(
                worker.local_closure_revalidation.is_none(),
                "non-cleanup wrapper must NOT populate local_closure_revalidation"
            );
            assert!(
                shared.borrow().is_none(),
                "Q2: non-cleanup must NOT populate the shared batch cell",
            );
        }

        #[test]
        fn cleanup_revalidation_does_not_persist_records_before_engine_acceptance() {
            // Patch C-Q Q2 — the adapter must NOT touch
            // `<runtime_root>/checker-state/local-closure-records/`
            // during dispatch. Persistence is deferred to after the
            // engine accepts the cleanup response (post-`step_with_checkpoint_sink`).
            // This test exercises the adapter directly and asserts the
            // records dir stays empty regardless of what the adapter
            // would otherwise persist.
            let dir = tempdir().expect("tempdir");
            let repo = dir.path();
            seed_repo(repo);
            write_node(repo, "Foo", "trivial");
            let mut state = ProtocolState::default();
            state.cycle = 9;
            state.live.present_nodes.insert(NodeId::from("Foo"));
            state.proof_nodes.insert(NodeId::from("Foo"));
            state
                .local_closure_unverified_nodes
                .insert(NodeId::from("Foo"));

            // A Valid cleanup burst that carries a probe result for the
            // unverified node. Under bd513b5 the adapter builds the
            // same-burst issuance batch from this attached probe payload
            // (no disk probe), stashes it in the shared cell, and defers
            // ALL persistence to the post-acceptance sweep. `merge_
            // revalidation_batch` skips empty batches, so a real batch is
            // required to exercise the "stash without persisting" contract
            // (a default/empty response would legitimately leave the cell
            // None — nothing to defer). The engine simulation inside the
            // cleanup post-delta branch installs Foo's record and clears it
            // from the unverified set, so that branch returns an empty batch
            // and never touches the live probe runner.
            let mut probe = LocalClosureProbeOutput::default();
            probe.status = "ok".to_string();
            let mut snapshot = trellis_kernel::WorkingSnapshot::default();
            snapshot.present_nodes.insert(NodeId::from("Foo"));
            let mut worker_response = trellis_kernel::WorkerResponse::default();
            worker_response.status = ResponseStatus::Ok;
            worker_response.outcome = WorkerOutcome::Valid;
            worker_response.snapshot = snapshot;
            worker_response
                .local_closure_results
                .insert(NodeId::from("Foo"), probe);
            let responses = vec![WrapperResponse::Worker(worker_response)];
            let inner = StubAdapter { responses };
            let runtime_root_dir = tempdir().expect("runtime root");
            let runtime_root = runtime_root_dir.path();
            let records_dir = local_closure_records_dir(runtime_root);
            let shared: std::rc::Rc<std::cell::RefCell<Option<RevalidationBatch>>> =
                std::rc::Rc::new(std::cell::RefCell::new(None));
            let mut wrapper = ScheduledWorkerIssuanceAdapter {
                inner,
                state: &state,
                repo: repo.to_path_buf(),
                current_cycle: 9,
                shared_batch: shared.clone(),
            };
            let mut request = WrapperRequest::default();
            request.kind = RequestKind::Worker;
            request.worker_context.validation_kind = WorkerValidationKind::Cleanup;

            let _ = wrapper.dispatch(&request).expect("dispatch");

            // The records dir must NOT have been created or populated
            // by the adapter. Even if the dispatch failed (transport
            // error on the empty repo), the adapter must not have
            // written any persisted JSON.
            let records_present = records_dir.exists()
                && fs::read_dir(&records_dir).map(|d| d.count()).unwrap_or(0) > 0;
            assert!(
                !records_present,
                "Q2: cleanup adapter must NOT persist records to disk during dispatch — \
                 persistence is deferred to post-acceptance. Records dir state: \
                 exists={}, entry count={}",
                records_dir.exists(),
                if records_dir.exists() {
                    fs::read_dir(&records_dir).map(|d| d.count()).unwrap_or(0)
                } else {
                    0
                },
            );
            // The batch is stashed in the shared cell for the post-
            // acceptance sweep (`step_runtime` reads it).
            assert!(
                shared.borrow().is_some(),
                "Q2: cleanup adapter must populate the shared batch cell for the post-acceptance sweep",
            );
        }

        #[test]
        fn cleanup_revalidation_persists_records_only_after_engine_acceptance() {
            // Patch C-Q Q2 — partner test: the records dir gets
            // populated only by `step_runtime`'s post-acceptance
            // persistence sweep, which reads the shared cell. This
            // test simulates that sweep manually (the runtime/engine
            // wiring is exercised in the audit-flagged
            // integration-style harness; here we pin the unit-level
            // contract that the shared cell carries the batch and
            // that the sweep semantics are "persist iff the entry is
            // still in `state.local_closure_records`").
            let dir = tempdir().expect("tempdir");
            let repo = dir.path();
            seed_repo(repo);
            write_node(repo, "Foo", "trivial");
            let mut state = ProtocolState::default();
            state.cycle = 9;
            state.live.present_nodes.insert(NodeId::from("Foo"));
            state.proof_nodes.insert(NodeId::from("Foo"));
            state
                .local_closure_unverified_nodes
                .insert(NodeId::from("Foo"));

            // Pretend the engine accepted the batch and routed it
            // through `apply_revalidation_batch`, which inserted Foo
            // into `state.local_closure_records`. We mock that by
            // synthesizing a record directly.
            let record = compute_local_closure_record_inputs(
                repo,
                &NodeId::from("Foo"),
                &BTreeSet::new(),
                &BTreeMap::new(),
                &BTreeMap::new(),
                &BTreeMap::new(),
                "snap".to_string(),
                AxcheckStatus::Agreed,
            )
            .expect("compute record");
            state
                .local_closure_records
                .insert(NodeId::from("Foo"), record.clone());
            state
                .local_closure_unverified_nodes
                .remove(&NodeId::from("Foo"));

            // Build the batch the adapter would have produced.
            let mut batch = RevalidationBatch::default();
            batch.refreshed.push((NodeId::from("Foo"), record.clone()));

            // Manually emulate the `step_runtime` post-acceptance sweep.
            let runtime_root_dir = tempdir().expect("rt root");
            let runtime_root = runtime_root_dir.path();
            let records_dir = local_closure_records_dir(runtime_root);
            for (node, _r) in &batch.refreshed {
                if let Some(accepted) = state.local_closure_records.get(node) {
                    persist_record_to_disk(&records_dir, accepted, 9).expect("persist");
                }
            }
            let on_disk = records_dir.join(trellis_kernel::runtime::persisted_record_file_name(
                &NodeId::from("Foo"),
            ));
            assert!(
                on_disk.exists(),
                "Q2: after engine acceptance, the record must land on disk via the post-acceptance sweep",
            );
        }

        #[test]
        fn cleanup_revalidation_post_acceptance_sweep_skips_engine_rejected_entries() {
            // Patch C-Q Q2 — defense in depth: the post-acceptance
            // sweep filters by `state.local_closure_records.contains_key`.
            // If the engine dropped a batch entry (e.g.
            // `apply_revalidation_batch`'s eligibility filter rejected
            // it because the node became `Open` during the cleanup
            // delta), the sweep must NOT persist that entry — on-disk
            // state must mirror the kernel's view.
            let dir = tempdir().expect("tempdir");
            let repo = dir.path();
            seed_repo(repo);
            write_node(repo, "Foo", "trivial");
            let mut state = ProtocolState::default();
            state.cycle = 9;
            // Foo is in batch.refreshed but engine rejected
            // (not present in state.local_closure_records).
            // (Don't insert into records.)
            let record = compute_local_closure_record_inputs(
                repo,
                &NodeId::from("Foo"),
                &BTreeSet::new(),
                &BTreeMap::new(),
                &BTreeMap::new(),
                &BTreeMap::new(),
                "snap".to_string(),
                AxcheckStatus::Agreed,
            )
            .expect("compute record");
            let mut batch = RevalidationBatch::default();
            batch.refreshed.push((NodeId::from("Foo"), record));

            let runtime_root_dir = tempdir().expect("rt root");
            let runtime_root = runtime_root_dir.path();
            let records_dir = local_closure_records_dir(runtime_root);
            for (node, _r) in &batch.refreshed {
                if let Some(accepted) = state.local_closure_records.get(node) {
                    persist_record_to_disk(&records_dir, accepted, 9).expect("persist");
                }
            }
            let on_disk = records_dir.join(trellis_kernel::runtime::persisted_record_file_name(
                &NodeId::from("Foo"),
            ));
            assert!(
                !on_disk.exists(),
                "Q2: post-acceptance sweep must NOT persist an entry that the engine dropped",
            );
        }

